// Generate a synthetic 802.11 capture.
//
// This exists so the analyzer is reproducible. A pcap of a real network is not
// something to commit to a public repository (it contains the MAC address of
// every device in range) and nobody cloning this repo has a monitor-mode
// adapter to hand. So the committed sample is synthesised from
// locally administered addresses, and it is generated by code, which means the
// analyzer's output can be checked against known ground truth in the tests.
//
// Everything here is fabricated. No real network, device or handshake is
// represented. Frames carry the right header fields and information elements;
// payloads are filler, because the analyzer only ever reads metadata.
//
// The scenario, chosen to exercise every detector:
//
//   1. Three access points beacon: WPA2-PSK, WPA3-SAE, and a legacy TKIP AP.
//   2. A station probes, open-authenticates and associates to the WPA2 AP.
//   3. A four-way handshake completes; the AP leaks a PMKID in message 1.
//   4. Encrypted data flows, with control frames interleaved.
//   5. An attacker floods forged deauths at the station, spoofing the AP.
//   6. The station reconnects and a second handshake is captured.
//   7. A second station does SAE authentication against the WPA3 AP.
//   8. An "evil twin" beacons the WPA2 network's SSID with no security at all.
#pragma once

#include <string>
#include <vector>

#include "common/bytes.hpp"
#include "wifi/pcap.hpp"

namespace airlock::wifi::synth {

// Locally administered addresses (the 0x02 bit is set), so none of these can
// collide with a real manufacturer-assigned MAC.
inline constexpr const char* AP_WPA2 = "02:00:00:aa:00:01";
inline constexpr const char* AP_WPA3 = "02:00:00:bb:00:01";
inline constexpr const char* AP_LEGACY = "02:00:00:cc:00:01";
inline constexpr const char* AP_EVIL_TWIN = "02:00:00:de:ad:01";
inline constexpr const char* STA_ONE = "02:00:00:11:11:11";
inline constexpr const char* STA_TWO = "02:00:00:22:22:22";
inline constexpr const char* ATTACKER = "02:00:00:66:66:66";
inline constexpr const char* BROADCAST = "ff:ff:ff:ff:ff:ff";

inline constexpr const char* SSID_WPA2 = "TestNet-WPA2";
inline constexpr const char* SSID_WPA3 = "TestNet-WPA3";
inline constexpr const char* SSID_LEGACY = "TestNet-Legacy";

// The fabricated PMKID the WPA2 AP leaks in its first message 1.
Bytes pmkid();

// Every frame of the scenario, timestamped. Deterministic: the same bytes on
// every run, so the tests can assert on exact counts.
std::vector<PcapRecord> build_capture();

// Generate the capture and write it to `path`. Returns the frame count.
std::size_t write_capture(const std::string& path);

}  // namespace airlock::wifi::synth
